function GradientDefs() {
  return (
    <defs>
      <linearGradient id="tmLogoGradient" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stopColor="#6C59F4" />
        <stop offset="1" stopColor="#5B47F0" />
      </linearGradient>
    </defs>
  );
}

/** Full logo: icon + "Teamulate" wordmark. Set height via className (width scales). */
export function TeamulateLogo({
  className = "h-8 w-auto",
  wordmarkColor = "#0b1631",
}: {
  className?: string;
  wordmarkColor?: string;
}) {
  return (
    <svg viewBox="45 50 906 207" className={className} role="img" aria-label="Teamulate">
      <GradientDefs />
      {ICON}
      <g transform="translate(310 0) scale(0.855 1)">
        <path d={WORDMARK_PATH} fill={wordmarkColor} />
      </g>
    </svg>
  );
}

/** Icon-only mark for compact placements. */
export function TeamulateIcon({ className = "h-6 w-6" }: { className?: string }) {
  return (
    <svg viewBox="49 50 205 207" className={className} role="img" aria-label="Teamulate">
      <GradientDefs />
      {ICON}
    </svg>
  );
}
